function newProfile(){return {version:2,credits:1200,owned:['destroyer','frigate'],selected:'destroyer',upgrades:{},unlockedMission:0,claimed:[],wins:0};}
function cleanProfile(value){const p=newProfile();if(!value||value.version!==2)return p;p.credits=clamp(Math.floor(Number(value.credits)||0),0,999999);p.owned=PLAYABLE.filter(k=>['destroyer','frigate'].includes(k)||(Array.isArray(value.owned)&&value.owned.includes(k)));p.selected=p.owned.includes(value.selected)?value.selected:'destroyer';p.unlockedMission=clamp(Math.floor(Number(value.unlockedMission)||0),0,2);p.wins=clamp(Math.floor(Number(value.wins)||0),0,99999);p.claimed=Array.isArray(value.claimed)?value.claimed.filter(x=>typeof x==='string'&&x.length<100).slice(-300):[];for(const t of PLAYABLE){p.upgrades[t]={};for(const k of Object.keys(UPGRADES))p.upgrades[t][k]=clamp(Math.floor(Number(value.upgrades?.[t]?.[k])||0),0,4);}return p;}
function buy(profile,kind,key){if(kind==='ship'){if(!PLAYABLE.includes(key)||profile.owned.includes(key))return {ok:false,reason:'เรือลำนี้อยู่ในกองเรือแล้ว'};const cost=TYPES[key].price;if(profile.credits<cost)return {ok:false,reason:'เครดิตไม่พอ'};profile.credits-=cost;profile.owned.push(key);return {ok:true};}const type=profile.selected;if(!UPGRADES[key]||!profile.owned.includes(type))return {ok:false,reason:'เลือกเรือที่เป็นเจ้าของก่อน'};profile.upgrades[type]??={};const level=profile.upgrades[type][key]||0,max=key==='locks'?Math.min(4,6-TYPES[type].locks):4;if(level>=max)return {ok:false,reason:'อัปเกรดสูงสุดแล้ว'};const cost=UPGRADES[key].cost*(level+1);if(profile.credits<cost)return {ok:false,reason:'เครดิตไม่พอ'};profile.credits-=cost;profile.upgrades[type][key]=level+1;return {ok:true};}
function reward(profile,state){if(!state.ended||profile.claimed.includes(state.matchId))return 0;const amount=state.ended.credits;profile.credits=clamp(profile.credits+amount,0,999999);profile.claimed.push(state.matchId);profile.claimed=profile.claimed.slice(-300);if(state.ended.win){profile.wins++;profile.unlockedMission=Math.max(profile.unlockedMission,Math.min(2,state.mission+1));}return amount;}
