 setTarget(x,y,shipId=this.state.selected){if(!Number.isFinite(x)||!Number.isFinite(y))return;const p={x:clamp(x,.5,GRID-.5),y:clamp(y,.5,GRID-.5)},sh=this.state.ships.find(x=>x.id===shipId);if(sh)sh.aim=p;if(shipId===this.state.selected)this.state.target=p;}
 input(shipId,input){const sh=this.state.ships.find(x=>x.id===shipId&&x.hp>0);if(!sh)return;sh.input={throttle:clamp(Number(input.throttle)||0,-1,1),steer:clamp(Number(input.steer)||0,-1,1)};sh.controlAt=this.state.time;if(sh.input.throttle||sh.input.steer)sh.dest=null;}
 isVisible(e){return e.team==='player'||e.hp>0&&this.state.time<=e.visibleUntil;}
