  const cd={gun:'gunCD',missile:'missileCD',torpedo:'torpedoCD',scan:'scanCD',defense:'defenseCD',repair:'repairCD',anchor:'anchorCD'}[action];if(!cd)return fail('คำสั่งไม่ถูกต้อง');if(sh[cd]>.01)return fail('พร้อมอีก '+Math.ceil(sh[cd])+' วินาที');
  if(action==='gun'){
   if(!sh.damage)return fail('เรือลำนี้ไม่มีปืน');const d=dist(sh,t);if(d>sh.range||d<1)return fail('เป้าอยู่นอกระยะปืน '+sh.range+' ช่อง');const wanted=Math.atan2(t.x-sh.x,t.y-sh.y);if(Math.abs(angleDiff(wanted,sh.turret))>.13)return fail('ป้อมปืนกำลังหมุนเข้าหาเป้า');
   sh.gunCD=sh.reload;sh.recoil=.35;const barrels=TYPES[sh.type].turrets||1,boost=sh.boostUntil>s.time?1.7:1;sh.boostUntil=0;for(let i=0;i<barrels;i++){const spread=(.06+d*.005)*(sh.velocity>.8?1.4:1);this.launch(sh,{x:t.x+(this.rand()-.5)*spread,y:t.y+(this.rand()-.5)*spread},'shell',sh.damage*boost/barrels,null,i*.12);}this.emit('fire',{kind:'shell',ship:sh});
  }
  if(action==='missile'){if(sh.missiles<=0)return fail('จรวดหมด');const targets=sh.locks.map(id=>s.ships.find(e=>e.id===id&&e.hp>0)).filter(e=>e&&sh.lockProgress[e.id]>=1&&this.isVisible(e)&&dist(sh,e)<=20);if(!targets.length)return fail('เลือกศัตรู → กด L → รอสถานะล็อกพร้อม');const n=Math.min(sh.missiles,targets.length);targets.slice(0,n).forEach((e,i)=>this.launch(sh,e,'missile',sh.missileDamage,e.id,i*.22));sh.missiles-=n;sh.missileCD=8;this.emit('fire',{kind:'missile',ship:sh});}
  if(action==='torpedo'){if(sh.torpedoes<=0)return fail('ตอร์ปิโดหมดหรือเรือลำนี้ไม่มีตอร์ปิโด');if(dist(sh,t)>16||dist(sh,t)<1)return fail('เลือกเป้าในระยะ 1–16 ช่อง');const e=s.ships.find(e=>e.team!==sh.team&&e.hp>0&&this.isVisible(e)&&dist(e,t)<1.3);this.launch(sh,t,'torpedo',sh.torpedoDamage,e?.id||null);sh.torpedoes--;sh.torpedoCD=11;this.emit('fire',{kind:'torpedo',ship:sh});}
  if(action==='scan'){sh.scanCD=21;s.scans.push({x:sh.x,y:sh.y,start:s.time,end:s.time+15,radius:11});for(const e of s.ships)if(e.team!==sh.team&&e.hp>0&&dist(sh,e)<11)this.reveal(e,15);this.emit('scan',{ship:sh});}
