  if(action==='anchor'){if(sh.type!=='battleship')return fail('ใช้ได้เฉพาะ VANGUARD');sh.anchorCD=35;sh.anchorUntil=s.time+3;sh.boostUntil=s.time+13;sh.velocity*=.25;sh.dest=null;sh.throttle=0;sh.turnRate=1;this.effect('splash',sh.x,sh.y,1.5);}
