  if(friend){if(sh.hp<sh.maxHP*.52)this.action('repair',sh.id);if(s.projectiles.some(p=>p.team!=='player'&&dist(p,sh)<4.8)||s.drones.some(d=>dist(d,sh)<4.8))this.action('defense',sh.id);if(s.time>3)this.action('scan',sh.id);}
